const PATHS=[
 ...COTTONWOOD_TRACKS,
 [[0,128],[0,138],[18,150],[47,171],[83,184]],                         // river crossing -> north meadow
 [[0,10],[13,-11],[28,-30],[44,-46],[50,-53]],                       // ranch -> Cottonwood
 [[-7,3],[-26,7],[-46,2],[-63,-6],[-71,-10]],                        // ranch -> Home Pasture
 [[2,15],[7,44],[4,72],[1,98],[0,112]],                              // ranch -> the river bridge
 [[53,-57],[96,-70],[140,-84],[184,-97],[214,-105]],                 // Cottonwood -> Barleyfold
 [[-30,-20],[-33,-38],[-31,-52],[-30,-58]],                          // pasture road -> Hollowpeak Pines
];
const PATH_W=2.9;
const villageGroundZones=COTTONWOOD_PUBLIC.map(q=>({...q}));
// A maintained yard and clipped trail shoulders give way gradually to meadow.
function managedGrass(x,z){
 return managedGroundsAt(x,z,Math.max(1-THREE.MathUtils.smoothstep(Math.hypot(x*.94,z*1.12),38,82),
  1-THREE.MathUtils.smoothstep(Math.min(pathDist(x,z),G.worldPaths?.trackDist(x,z)??Infinity),2.6,5.8)));
}
const _PSEG=(()=>{                                                   // flattened into segments once
 const out=[];
 for(const pl of PATHS)for(let i=0;i<pl.length-1;i++){
  const a=pl[i],b=pl[i+1];
  out.push({ax:a[0],az:a[1],dx:b[0]-a[0],dz:b[1]-a[1],
   len2:(b[0]-a[0])*(b[0]-a[0])+(b[1]-a[1])*(b[1]-a[1]),
   lo:Math.min(a[0],b[0])-8,hi:Math.max(a[0],b[0])+8,zlo:Math.min(a[1],b[1])-8,zhi:Math.max(a[1],b[1])+8});
 }
 return out;
})();
function pathDist(x,z){
 let best=1e9;
 for(const s of _PSEG){
  if(x<s.lo||x>s.hi||z<s.zlo||z>s.zhi)continue;                      // cheap reject first
  let t=((x-s.ax)*s.dx+(z-s.az)*s.dz)/s.len2; t=t<0?0:t>1?1:t;
  const px=s.ax+s.dx*t-x, pz=s.az+s.dz*t-z;
  const d=px*px+pz*pz; if(d<best)best=d;
 }
 let distance=Math.sqrt(best);
 for(const q of villageGroundZones){
  const dx=x-q.x,dz=z-q.z;
  if(Math.abs(dx)>q.halfX+Math.max(Math.abs(q.minZ),Math.abs(q.maxZ))+8||Math.abs(dz)>q.halfX+Math.max(Math.abs(q.minZ),Math.abs(q.maxZ))+8)continue;
  const lx=dx*q.cos-dz*q.sin,lz=dx*q.sin+dz*q.cos;
  const edge=Math.hypot(Math.max(0,Math.abs(lx)-q.halfX),Math.max(0,q.minZ-lz,lz-q.maxZ));
  distance=Math.min(distance,edge===0?0:edge+2.3);
 }
 return distance;
}

